/** Synthetic checkpoints captured by v1.2.4 (01fcce5d), never regenerated by head. */
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { gunzipSync } from "node:zlib";
import type { Engine } from "../src/runtime/engine.ts";
import type { HistoryRecording } from "../src/agent/history.ts";
import type { RecordedReplay } from "../src/agent/recordedReplay.ts";
import type { SoundOutput } from "../src/sound/sound.ts";

export const releasedSound = JSON.parse(
  gunzipSync(readFileSync(new URL("formats/sound-1.2.4.json.gz", import.meta.url))).toString(
    "utf8",
  ),
) as {
  release: string;
  commit: string;
  captures: {
    name: string;
    device: number;
    period: number;
    ticks: number;
    tape: RecordedReplay;
    tests: string;
    history: HistoryRecording;
  }[];
};

const speaker = (divisor: number | null): SoundOutput => ({ kind: "speaker", divisor });
const psg = (bytes: number[]): SoundOutput => ({ kind: "psg", bytes });
const off = psg([0x9f, 0xbf, 0xdf, 0xff]);
/** Hand-calculated next-heartbeat schedules; see fidelity.md's migration rule. */
const EXPECTED: Record<string, { complete: number; outputs: [number, SoundOutput][] }> = {
  "speaker-review": {
    complete: 2,
    outputs: [
      [1, speaker(12)],
      [2, speaker(null)],
    ],
  },
  "speaker-start": {
    complete: 14,
    outputs: [
      [1, speaker(12)],
      [4, speaker(12)],
      [7, speaker(12)],
      [10, speaker(12)],
      [13, speaker(12)],
      [14, speaker(null)],
    ],
  },
  "speaker-middle": {
    complete: 11,
    outputs: [
      [1, speaker(12)],
      [4, speaker(12)],
      [7, speaker(12)],
      [10, speaker(12)],
      [11, speaker(null)],
    ],
  },
  "speaker-near-end": { complete: 1, outputs: [[1, speaker(null)]] },
  "speaker-period-zero": { complete: 1, outputs: [[1, speaker(null)]] },
  "speaker-partial-trailing": {
    complete: 2,
    outputs: [
      [1, speaker(408)],
      [2, speaker(null)],
    ],
  },
  "speaker-true-boundary": {
    complete: 2,
    outputs: [
      [1, speaker(408)],
      [2, speaker(null)],
    ],
  },
  "psg-review": {
    complete: 4,
    outputs: [
      [2, psg([0x81])],
      [4, off],
    ],
  },
  "psg-middle": {
    complete: 23,
    outputs: [
      [1, psg([0x81])],
      [7, psg([0x81])],
      [13, psg([0x81])],
      [19, psg([0x81])],
      [23, off],
    ],
  },
  "psg-near-end": { complete: 2, outputs: [[2, off]] },
  "psg-period-zero": {
    complete: 11,
    outputs: [
      [1, psg([0x81])],
      [3, psg([0x81])],
      [5, psg([0x81])],
      [7, psg([0x81])],
      [9, psg([0x81])],
      [11, off],
    ],
  },
};

export function assertSoundContinuation(
  engine: Engine,
  name: string,
  outputs?: SoundOutput[],
): void {
  const expected = EXPECTED[name]!;
  assert.equal(engine.flags[40], 0);
  for (let beat = 1; beat <= expected.complete; beat++) {
    if (outputs) outputs.length = 0;
    engine.soundTick();
    if (outputs)
      assert.deepEqual(
        outputs,
        expected.outputs.filter(([at]) => at === beat).map(([, output]) => output),
        `heartbeat ${beat}`,
      );
    assert.equal(
      engine.flags[40],
      beat === expected.complete ? 1 : 0,
      `done flag at heartbeat ${beat}`,
    );
    engine.tick();
    assert.equal(
      engine.vars[41],
      beat === expected.complete ? 77 : 0,
      `game observes completion at heartbeat ${beat}`,
    );
  }
  if (outputs) outputs.length = 0;
  engine.soundTick();
  if (outputs) assert.deepEqual(outputs, [], "completed sound stays stopped");
}
